export function EcosystemSection() {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      const container = scrollRef.current;
      container.scrollLeft =
        (container.scrollWidth - container.clientWidth) / 2;
    }
  }, []);

  return (
    <section className="bg-blue-100/50 py-16 md:py-24">
      <div className="container mx-auto px-4">
        <div className="mb-10 text-center md:mb-16">
          <h2 className="mb-4 text-3xl font-bold md:text-5xl">
            Skolist Ecosystem
          </h2>
          <p className="mx-auto max-w-2xl text-sm text-gray-600 md:text-base">
            Each Skolist product solves a specific problem, but together they
            create a complete learning loop, measure, understand, support, and
            improve learning at scale.
          </p>
        </div>

        {/* Scrollable container for mobile, centered for desktop */}
        <div
          ref={scrollRef}
          className="-mx-4 overflow-x-auto px-4 pb-4 md:mx-0 md:overflow-visible md:px-0"
        >
          <div className="flex min-w-[600px] origin-top scale-75 justify-center transition-transform duration-300 sm:scale-90 md:min-w-0 md:scale-100 lg:scale-100">
            <EcosystemSvg />
          </div>
        </div>
      </div>
    </section>
  );
}
